// v16.xx, HIS NOTE (2026-10-09): "gear that drops from enemies dying needs to be better". A pillager's body held what he had looted (two
// to four rolls, mostly on the body and locker tables, which are bandages, ammo, wire and boards) and his own gun. Every body now also
// carries one roll on the safe table (cores, titanium, optics, plates, medkits and real guns), and a man in a medium or heavy rig a
// second, so the fight pays like the loot it guards. Rolled at the death, never at the map build, so the seeded build is unchanged.
function bodyBonus(e){
  var out=[], n, RT, i, k;
  if(!e||e.kind!=='raider'||e.merc||e.friendlyPC||!LOOT||!LOOT.safe) return out;
  RT={none:0,light:1,medium:2,heavy:3}[e.rig]||0;
  n=1+(RT>=2?1:0);
  for(i=0;i<n;i++){ k=rollLoot(LOOT.safe); if(k) out.push(k); }
  return out;
}
function updateEnts(dt){

check:
{v:'VER',what:'his note: a dead pillager drops better gear, one safe table roll on every body and two for a medium or heavy rig',
 run:function(){
   if(typeof bodyBonus!=='function') return 'control: a dead pillager drops nothing extra';
   var bad=[], a=bodyBonus({kind:'raider',rig:'none'}), b=bodyBonus({kind:'raider',rig:'heavy'}), c=bodyBonus({kind:'raider',rig:'none',merc:1});
   if(a.length!==1) bad.push('a pillager in no rig drops '+a.length+' extra, not 1');
   if(b.length!==2) bad.push('a pillager in a heavy rig drops '+b.length+' extra, not 2');
   if(c.length) bad.push('your hire drops extra gear');
   var safe=(LOOT.safe||[]).map(function(r){ return r[0]; });
   a.concat(b).forEach(function(k){ if(safe.indexOf(k)<0&&k!=='KEY'&&!/^key_/.test(k)) bad.push(k+' is not from the safe table'); });
   var src=[].slice.call(document.scripts).map(function(s){ return s.text||''; }).join(''), nd='_drop.concat(body'+'Bonus(e))';
   if(src.indexOf(nd)<0) bad.push('the body drop never adds the bonus');
   return bad.length?bad.join('; '):null; }},
